function p = bisectionWhile(a,b,f,tol)
  p = a;
  err = abs(b-a);
  FA = f(a);
  while (err>tol)
    p = a + (b-a)/2;
    FP = f(p);
    err=err/2;
    if (FP == 0)
      return
    end%if
    if (FA*FP > 0)
      a = p;
      FA = FP;
    else
      b = p;
    end%if
  end%while
end%function

